def h(b:bytes)->str: return hashlib.sha256(b).hexdigest()
def dec(s:str)->bytes: return zlib.decompress(base64.b64decode(s))
def norm(s:str)->str: return s.replace("\r\n","\n").replace("\r","\n")
def text(b:bytes)->str: return norm(b.decode("utf-8"))

def payload(path:str, which:str)->bytes:
    r=RECORDS[path]
    b=dec(r[which+"_z"])
    if h(b)!=r[which+"_sha256"]:
        raise RuntimeError(f"embedded {which} payload hash drift: {path}")
    return b

def between(src:str,start:str,end:str)->str:
    a=src.find(start)
    if a<0: raise RuntimeError(f"semantic start anchor missing: {start}")
    b=src.find(end,a+len(start))
    if b<0: raise RuntimeError(f"semantic end anchor missing: {end}")
    return src[a:b]

def semantic_validate(targets:dict[str,bytes])->None:
    sh=text(targets[ALLOWLIST[0]])
    st=text(targets[ALLOWLIST[1]])
    zoom=text(targets[ALLOWLIST[2]])
    swipe=text(targets[ALLOWLIST[3]])
    cap=text(targets[ALLOWLIST[4]])
    cam=text(targets[ALLOWLIST[5]])
    dj=text(targets[ALLOWLIST[6]])
    saver=text(targets[ALLOWLIST[7]])
    cpp=text(targets[ALLOWLIST[8]])
    hh=text(targets[ALLOWLIST[9]])
    required=[
      ("active Spatial parity marker","IRIS_26527_FINAL_MGC_REJECTION_ALIGNMENT_PARITY",sh+st),
      ("pixel-difference 2x shader","val rejectionPixelDifferenceDownsample",sh),
      ("acceptance preserving max","max(deltaWeight, centerWeight)",sh),
      ("acceptance names","uOriginalWeight",sh),
      ("active unsigned RAW/4 luma sampler","uniform highp usampler2D uBaseLuma",sh),
      ("final alignment owner","IRIS_26527_FINAL_ALIGNMENT_FIELD_OWNER",st),
      ("merge consumes final alignment","val bayerAlignment = alignment.texture",st),
      ("RAW/4 luma pyramid","referenceGrayPyramid[1].texture",st),
      ("pixel-difference downsample call","renderPixelDifferenceDownsample(rawPixelDifference, pixelDifference)",st),
      ("runtime acceptance telemetry","IRIS_26527_TEMPORAL_ACCEPTANCE_STAGES",st),
      ("requested/displayed zoom","IRIS_26527_REQUESTED_VS_DISPLAYED_ZOOM",zoom),
      ("sequential optical anchors","IRIS_26527_SEQUENTIAL_OPTICAL_ANCHORS",zoom),
      ("pinch gesture ownership","IRIS_26527_PINCH_OWNS_GESTURE_STREAM",swipe),
      ("session route owner","IRIS_26527_SESSION_BOUND_ROUTE_OWNER",cap),
      ("single surface route authority","IRIS_26527_SINGLE_ROUTE_AUTHORITY_SURFACE",cap),
      ("single setup route authority","IRIS_26527_SINGLE_ROUTE_AUTHORITY_SETUP",cap),
      ("adaptive logical/physical search","IRIS_26527_ADAPTIVE_LOGICAL_PHYSICAL_SEARCH",cap),
      ("physical output binding","config.setPhysicalCameraId(irisSessionRoute.physicalOutputId);",cap),
      ("restart ordering","IRIS_26527_ROUTE_RESTART_ORDER",cap),
      ("curtain fail-safe","IRIS_26527_ZOOM_CURTAIN_FAILSAFE",cap),
      ("camera topology diagnostics","IRIS_26527_CAMERA_TOPOLOGY_DIAGNOSTICS",cam),
      ("DNG preview Java API","setEmbeddedPreviewEnabled",dj),
      ("26525 DefaultCrop preserved","dngCreator.setDefaultCropZoom(parameters.motionV2OutputZoom);",saver),
      ("stacked still preview opt-in","dngCreator.setEmbeddedPreviewEnabled(true);",saver),
      ("native preview flag","embedded_preview_enabled",hh),
      ("native preview renderer","iris26527BuildPreview",cpp),
      ("native SubIFD tag","SetCustomFieldULong(330, 0u)",cpp),
      ("native SubIFD promotion","iris26527PromoteSecondIfdToSubIfd",cpp),
      ("main Bayer strip offset preserved","metadata.strip_offset = dng_image0->GetStripOffset();",cpp),
    ]
    for name,token,src in required:
        if token not in src: raise RuntimeError(f"semantic target missing {name}: {token}")
    for token in ("convertBayerAlignment","renderBayerAlignment(","renderMergeDomainFlow("):
        if token in sh+st: raise RuntimeError(f"obsolete Spatial stage survived: {token}")
    if "private val mergeWeightWidth = rejectionWidth / 2" not in st or "private val mergeWeightHeight = rejectionHeight / 2" not in st:
        raise RuntimeError("RAW/4 acceptance floor sizing missing")
    prep=st.find("private fun prepareTemporalFrame")
    d=st.find("renderDilation(rawReverseWeight, initialWeight)",prep)
    p=st.find("renderPixelDifferenceDownsample(rawPixelDifference, pixelDifference)",prep)
    f=st.find("renderRejectionFilterDownsample(",prep)
    post=st.find("renderRejectionPostprocess(",prep)
    if not (prep>=0 and d>prep and p>d and f>p and post>f):
        raise RuntimeError("final MGC rejection/acceptance stage order drift")
    if zoom.count("sRequestedGlobalZoom") < 3 or "chainedPendingOwnerCameraId" not in zoom:
        raise RuntimeError("requested/displayed or chained sequential zoom ownership incomplete")
    if "MotionEvent.ACTION_CANCEL" not in swipe:
        raise RuntimeError("pinch does not cancel previous one-finger gesture")
    surface=between(cap,"public final TextureView.SurfaceTextureListener","public CaptureController(")
    setup=between(cap,"private void setUpCameraOutputs","private IrisCameraRoute iris26527ResolveRoute") if False else ""
    if 'String curID = PhotonCamera.getSettings().mCameraID;' in surface or 'split("-")' in surface:
        raise RuntimeError("legacy surface camera-ID split authority survived")
    setup_start=cap.find("private void setUpCameraOutputs")
    setup_end=cap.find("/**",setup_start+50)
    setup=cap[setup_start:setup_end]
    if 'split("-")' in setup or "iris26527ResolveRoute" not in setup:
        raise RuntimeError("legacy setup camera-ID split authority survived")
    restart=between(cap,"public void restartCamera()","private Size getAspect")
    if restart.find("setUpCameraOutputs")<0 or restart.find("mCameraManager.openCamera")<0 or restart.find("setUpCameraOutputs")>restart.find("mCameraManager.openCamera"):
        raise RuntimeError("restart opens camera before route/output state is prepared")
    if cap.count("mIrisSessionRoutes.remove(cameraCaptureSession)") != 2:
        raise RuntimeError("session route cleanup cardinality drift")
    if "IRIS_26527_CURTAIN_FAILSAFE_MS = 1600L" not in cap:
        raise RuntimeError("zoom curtain fail-safe drift")
    if saver.count("dngCreator.setEmbeddedPreviewEnabled(true);") != 1:
        raise RuntimeError("stacked still preview opt-in cardinality drift")
    if cpp.count("SetCustomFieldULong(330, 0u)") != 1:
        raise RuntimeError("SubIFD tag cardinality drift")
    if "metadata.bps == 16 && !metadata.binning" not in cpp:
        raise RuntimeError("preview must remain 16-bit non-binned still-only native path")
    if "dng_writer.AddImage(dng_image0);" not in cpp or "dng_writer.AddImage(previewImage);" not in cpp:
        raise RuntimeError("main+preview IFD ordering missing")

def resolve(root:Path)->tuple[dict[str,bytes],dict[str,bytes]]:
    vp=root/"app/version.properties"
    if not vp.is_file(): raise RuntimeError("version.properties missing")
    v=norm(vp.read_text())
    if f"VERSION_NAME={EXPECTED_BASE_VERSION}" not in v or f"VERSION_BUILD={EXPECTED_BASE_BUILD}" not in v:
        raise RuntimeError("base version/build is not exact successful 26526")
    bases={}; targets={}
    for path in ALLOWLIST:
        p=root/path
        if not p.is_file(): raise RuntimeError(f"missing predecessor owner: {path}")
        got=p.read_bytes(); exp=RECORDS[path]["base_sha256"]
        if h(got)!=exp: raise RuntimeError(f"exact-26526 owner hash mismatch: {path} got={h(got)} expected={exp}")
        if got!=payload(path,"base"): raise RuntimeError(f"predecessor byte mismatch: {path}")
        bases[path]=got; targets[path]=payload(path,"target")
    semantic_validate(targets)
    return bases,targets

def patch_bytes(old:dict[str,bytes],new:dict[str,bytes])->bytes:
    chunks=[]
    for path in ALLOWLIST:
        a=text(old[path]).splitlines(True); b=text(new[path]).splitlines(True)
        chunks.extend(difflib.unified_diff(a,b,fromfile="a/"+path,tofile="b/"+path,n=3))
    return ''.join(chunks).encode()

def write_hash_file(path:Path,target:Path):
    path.write_text(f"{h(target.read_bytes())}  {target.name}\n")

def check_only(root:Path,patch_out:Path|None,rollback_out:Path|None,patch_sha:Path|None,rollback_sha:Path|None):
    bases,targets=resolve(root)
    forward=patch_bytes(bases,targets); rollback=patch_bytes(targets,bases)
    if not forward or not rollback: raise RuntimeError("runtime delta unexpectedly empty")
    if patch_out:
        patch_out.parent.mkdir(parents=True,exist_ok=True); patch_out.write_bytes(forward)
        if patch_sha: write_hash_file(patch_sha,patch_out)
    if rollback_out:
        rollback_out.parent.mkdir(parents=True,exist_ok=True); rollback_out.write_bytes(rollback)
        if rollback_sha: write_hash_file(rollback_sha,rollback_out)
    print("PASS: exact 10-owner 26527 transform resolved entirely in memory")
    print("PASS: target semantic validation passed")
    print("RUNTIME_CHANGED_FILES=10")
    return bases,targets

def apply(root:Path):
    _,targets=resolve(root)
    for path in ALLOWLIST: (root/path).write_bytes(targets[path])
    for path in ALLOWLIST:
        got=(root/path).read_bytes(); exp=RECORDS[path]["target_sha256"]
        if h(got)!=exp: raise RuntimeError(f"post-write target hash mismatch: {path}")
    print("PASS: 26527 exact target bytes written for 10 owners")

def self_test():
    for path in ALLOWLIST: payload(path,"base"); payload(path,"target")
    with tempfile.TemporaryDirectory(prefix="iris26527-selftest-") as td:
        r=Path(td); (r/"app").mkdir(); (r/"app/version.properties").write_text(
            f"VERSION_NAME={EXPECTED_BASE_VERSION}\nVERSION_BUILD={EXPECTED_BASE_BUILD}\n")
        for path in ALLOWLIST:
            p=r/path; p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(payload(path,"base"))
        bases,targets=check_only(r,None,None,None,None)
        apply(r)
        for path in ALLOWLIST: assert (r/path).read_bytes()==targets[path]
        p=r/ALLOWLIST[0]; p.write_bytes(payload(ALLOWLIST[0],"base")+b"x")
        try: resolve(r)
        except RuntimeError: pass
        else: raise RuntimeError("negative predecessor-drift self-test failed")
    print("PASS: 26527 transformer self-test including negative predecessor hash gate")

def main():
    ap=argparse.ArgumentParser(); ap.add_argument("root",nargs="?"); ap.add_argument("--self-test",action="store_true")
    ap.add_argument("--check-only",action="store_true"); ap.add_argument("--patch-out"); ap.add_argument("--rollback-out")
    ap.add_argument("--patch-sha-out"); ap.add_argument("--rollback-sha-out")
    a=ap.parse_args()
    if a.self_test: self_test(); return
    if not a.root: ap.error("root required unless --self-test")
    r=Path(a.root)
    if a.check_only:
        check_only(r,Path(a.patch_out) if a.patch_out else None,Path(a.rollback_out) if a.rollback_out else None,
                   Path(a.patch_sha_out) if a.patch_sha_out else None,Path(a.rollback_sha_out) if a.rollback_sha_out else None)
    else: apply(r)
if __name__=="__main__": main()
